head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[$p > M > executeSubmission]<br/>등록된 submission 을 실행하여 서버와 통신합니다.",
    "validation" : [
        "submissionId(필수) 파라미터로 실행할 Submission 의 ID 를 설정할 수 있어야 합니다.",
        "requestData(선택) 파라미터로 요청 데이터를 설정할 수 있으며, 설정 시 submission 에 정의된 ref 속성은 무시되어야 합니다.",
        "info(선택) 파라미터로 전송 중 비활성화(disabled) 할 컴포넌트를 설정할 수 있어야 합니다. (컴포넌트의 ID 문자열이 아닌 컴포넌트 객체를 설정)",
        "info 파라미터에 여러 개의 컴포넌트를 배열로 설정할 수 있어야 합니다.",
        "info 파라미터에 포함된 컴포넌트는 Submission 실행이 완료된 후 다시 활성화되어야 합니다.",
        "submissionId 파라미터가 null 또는 빈 문자열이면 Submission 을 실행하지 않아야 합니다."
    ]
}



scwin.onpageload = function () {
    $c.gcm.createCommonDatalist();
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// 현재 시나리오 저장 (submitdone 핸들러에서 사용)
scwin.currentScenario = null;
// 요청 body 캡처용
scwin.lastRequestBody = null;
// disabled 상태 캡처 결과
scwin.disabledSnapshot = null;

// XHR.send 후킹 - 실제 전송 body 가로채기 (requestData 검증용)
(function () {
    var originalSend = XMLHttpRequest.prototype.send;
    XMLHttpRequest.prototype.send = function (body) {
        try {
            scwin.lastRequestBody = body;
        } catch (e) {}
        return originalSend.apply(this, arguments);
    };
})();



// sbm_basic 의 submitdone 공통 핸들러
scwin.sbm_basic_submitdone = function (e) {
    var scenario = scwin.currentScenario;
    var rowCount = dlt_userList.getRowCount();

    if (scenario === "1") {
        wf_body_bottom.getObj("scwin").setReturnValue("executeSubmission 실행 / 로드된 행 수 = " + rowCount);
    } else if (scenario === "2") {
        var body = scwin.lastRequestBody || "";
        var bodyStr = "";
        if (typeof body === "string") {
            bodyStr = body;
        } else {
            try {
                bodyStr = JSON.stringify(body);
            } catch (ex) {
                bodyStr = String(body);
            }
        }
        var hasRequestData = (bodyStr.indexOf("TYPE") > -1 && bodyStr.indexOf("U00001") > -1);
        var hasRefSource = (bodyStr.indexOf("FROM_REF_SOURCE") > -1);
        wf_body_bottom.getObj("scwin").setReturnValue("body 에 requestData(TYPE=U00001) 포함 : " + hasRequestData);
        wf_body_bottom.getObj("scwin").setReturnValue("body 에 ref source(FROM_REF_SOURCE) 포함 : " + hasRefSource + " (false 여야 ref 무시 PASS)");
        wf_body_bottom.getObj("scwin").setReturnValue("전송 body : " + bodyStr);
    } else if (scenario === "3") {
        // 실행 직후 스냅샷과 완료 후 상태를 함께 출력
        var afterDisabled = btn_target1.getDisabled();
        var snap = scwin.disabledSnapshot || {};
        wf_body_bottom.getObj("scwin").setReturnValue(
            "btn_target1 실행 직후 disabled=" + snap.before + " → 완료 후 disabled=" + afterDisabled
        );
    } else if (scenario === "4") {
        var snap4 = scwin.disabledSnapshot || {};
        var afterList = [
            btn_target1.getDisabled(),
            btn_target2.getDisabled(),
            ibx_target1.getDisabled()
        ];
        wf_body_bottom.getObj("scwin").setReturnValue(
            "실행 직후 disabled=[" + snap4.before.join(",") + "] → 완료 후 [" + afterList.join(",") + "]"
        );
        wf_body_bottom.getObj("scwin").setReturnValue(
            "3개 컴포넌트 실행 중 모두 비활성화됨 → 완료 후 모두 재활성화"
        );
    }
};

scwin.sbm_basic_submiterror = function (e) {
    wf_body_bottom.getObj("scwin").setReturnValue("submitErrorHandler: errorType=" + e.errorType);
};



scwin.btn_executeSubmission_onclick = function () {
    var scenario = par_scenario.getValue();
    scwin.currentScenario = scenario;
    scwin.lastRequestBody = null;
    scwin.disabledSnapshot = null;

    // 매 시나리오 실행 시 이전 데이터 제거
    dlt_userList.removeAll();

    // 기본 상태로 초기화 (이전 시나리오에서 비활성화된 상태가 남지 않도록)
    btn_target1.setDisabled(false);
    btn_target2.setDisabled(false);
    ibx_target1.setDisabled(false);

    if (scenario === "1") {
        // 시나리오 1 : 기본 실행 - submissionId 만 설정
        wf_body_bottom.getObj("scwin").setReturnValue("── 시나리오 1 : 기본 실행 ──");
        $p.executeSubmission("sbm_basic");
    } else if (scenario === "2") {
        // 시나리오 2 : requestData 설정 - 두번째 파라미터로 요청 데이터 전달
        wf_body_bottom.getObj("scwin").setReturnValue("── 시나리오 2 : requestData 설정 ──");
        $p.executeSubmission("sbm_basic", { "TYPE" : "U00001", "CODE" : "ABC123" });
    } else if (scenario === "3") {
        // 시나리오 3 : info 단일 컴포넌트 - 전송 중 비활성화
        wf_body_bottom.getObj("scwin").setReturnValue("── 시나리오 3 : info 단일 컴포넌트 비활성화 ──");
        $p.executeSubmission("sbm_basic", null, btn_target1);
        // 호출 직후(동기적으로) disabled 상태 캡처
        scwin.disabledSnapshot = { before : btn_target1.getDisabled() };
    } else if (scenario === "4") {
        // 시나리오 4 : info 배열 - 복수 컴포넌트 비활성화
        wf_body_bottom.getObj("scwin").setReturnValue("── 시나리오 4 : info 배열 복수 컴포넌트 비활성화 ──");
        $p.executeSubmission("sbm_basic", null, [btn_target1, btn_target2, ibx_target1]);
        // 호출 직후(동기적으로) 3개 컴포넌트 disabled 상태 캡처
        scwin.disabledSnapshot = { before : [
            btn_target1.getDisabled(),
            btn_target2.getDisabled(),
            ibx_target1.getDisabled()
        ]};
    } else if (scenario === "5") {
        // 시나리오 5 : submissionId 가 null 또는 빈 문자열 → 실행하지 않음
        wf_body_bottom.getObj("scwin").setReturnValue("── 시나리오 5 : submissionId = null / 빈 문자열 ──");

        // submitdone/submiterror 트리거 감지를 위해 타임스탬프 저장
        var beforeRowCount = dlt_userList.getRowCount();

        $p.executeSubmission(null);
        $p.executeSubmission("");

        // 500ms 후 상태 확인 (통신 미발생 → 데이터 변화 없음)
        setTimeout(function () {
            var afterRowCount = dlt_userList.getRowCount();
            wf_body_bottom.getObj("scwin").setReturnValue(
                "executeSubmission(null) / executeSubmission('') 호출 → 행 수 변화 : " + beforeRowCount + " → " + afterRowCount +
                " (미실행 : " + (beforeRowCount === afterRowCount) + ")"
            );
        }, 500);
    }
};
